module.exports = "<div class=\"content-wraper\">\r\n    <!-- CONTENT-->\r\n    <section class=\"container-fluid clearfix fletesAFacturar\">\r\n        <!--Title-->\r\n        <div class=\"row titleSection\">\r\n            <div class=\"col-xs-12 col-sm-10\">Fletes: <strong>Viajes a facturar</strong> </div>\r\n            <div class=\"col-xs-12 col-sm-2\">\r\n                <spinner-small></spinner-small>\r\n                <a (click)=\"exportExcel()\" href=\"#\" style=\"text-decoration:none!important\" *ngIf=\"!this.spinnerSmallComponent.visible\">\r\n                    <div class=\"btnSection animate\">Exportar <span class=\"fa  fa-file-excel-o\"></span></div>\r\n                </a>\r\n            </div>\r\n        </div>\r\n        <!--End Title-->\r\n        <div class=\"row  myRow mySearch espacios-sm\">\r\n            <div class=\"col-xs-12 col-md-12 rounded shadow animate\">\r\n                <title-caps>Refinar resultados</title-caps>\r\n                <hr>\r\n                <div id=\"searchFecha\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Ver:\r\n                    <filtro-fecha (ClickEvent)=\"getData()\"></filtro-fecha>\r\n                </div>\r\n                <div id=\"searchCCPP\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Por N&ordm; CCPP:\r\n                    <div class=\"styled-select\">\r\n                        <input type=\"search\" class=\"\" placeholder=\"\" [value]=\"filtroCCPP\" (input)=\"filtroCCPP = $event.target.value\" aria-controls=\"tableModal\">\r\n                    </div>\r\n                </div>\r\n                <div id=\"searchProforma\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Por N&ordm; Proforma:\r\n                    <div class=\"styled-select\">\r\n                        <input type=\"search\" class=\"\" placeholder=\"\" [value]=\"filtroProforma\" (input)=\"filtroProforma = $event.target.value\" aria-controls=\"tableModal\">\r\n                    </div>\r\n                </div>\r\n                <div id=\"searchProducto\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Por Producto:\r\n                    <div class=\"styled-select\">\r\n                        <dropdown [tipoDropdown]=\"'filtroVariable'\" [options]=\"filtroProducto\" (select)=\"setFiltroProducto($event)\"></dropdown>\r\n                    </div>\r\n                </div>\r\n                <div id=\"showSearch\" onClick=\"openSearch()\">\r\n                    <div style=\"\">\r\n                        <li class=\"fa fa-angle-double-right\" aria-hidden=\"true\"></li>\r\n                    </div>\r\n                    <div>VER MÁS OPCIONES DE BÚSQUEDA</div>\r\n                </div>\r\n                <div id=\"hideSearch\" onClick=\"closeSearch()\">\r\n                    <div style=\"\">\r\n                        <li class=\"fa fa-times\" aria-hidden=\"true\"></li>\r\n                    </div>\r\n                    <div>OCULTAR OPCIONES DE BÚSQUEDA</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"row  myRow mySearch espacios-sm espacios-sm-msj-spinner\">\r\n            <mensaje></mensaje>\r\n            <spinner></spinner>\r\n        </div>\r\n        <!--Add 1-->\r\n        <ng-container *ngIf=\"isVisible()\">\r\n            <div class=\"row myRow mySearch cargaDeDatos espacios-sm\" *ngFor=\"let proforma of data.viajes | customFilterContain: 'viajeItem' : 'ccpp' : filtroCCPP | customFilter : 'proforma' : filtroProforma | customFilterContain: 'viajeItem' : 'descMat' : productoSelected\">\r\n                <div class=\"rounded shadow clearfix espacios-sm\">\r\n                    <div class=\"row myRow \">\r\n                        <div class=\"col-xs-12 col-sm-10 titleSection\" style=\"border:  none;\">\r\n                            Proforma: <strong><span>Nº {{proforma.proforma}}</span></strong>\r\n                            <div class=\"titleExtraData\">\r\n                                <div id=\"extraDataFlete\">\r\n                                    <i class=\"fa fa-arrow-circle-right\" aria-hidden=\"true\"></i> Región <strong>{{proforma.regionId}} - {{proforma.region}}</strong><br>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <!--TABLA-->\r\n                    <div id=\"tablaFlete\" class=\"clearfix myTables\">\r\n                        <table id=\"tableModal\" class=\"display nowrap dataTable no-footer dtr-inline flete-a-facturar-table\" cellspacing=\"0\" role=\"grid\" aria-describedby=\"tableModal_info\" style=\"width: 100%;\">\r\n                            <thead>\r\n                                <tr role=\"row\">\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">CCPP</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Fecha</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Patente</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">KG CCPP</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Descripción</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Origen</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Destino</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Tarifa</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Peaje</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Playas</th>\r\n                                    <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Importe</th>\r\n                                </tr>\r\n                            </thead>\r\n                            <tbody>\r\n                                <tr role=\"row\" class=\"odd\" *ngFor=\"let viaje of proforma.viajeItem\">\r\n                                    <td tabindex=\"0\"><a (click)=\"showModalTableResponsive(viaje)\" href=\"#\" class=\"btnShowModal\"><i class=\"fa fa-plus fa-lg\" aria-hidden=\"true\"></i></a>{{viaje.ccpp}}</td>\r\n                                    <td>{{viaje.fechaCCPP}}</td>\r\n                                    <td>{{viaje.patente}}</td>\r\n                                    <td>{{viaje.kgString}}</td>\r\n                                    <td>{{viaje.descMat}}</td>\r\n                                    <td>{{viaje.origen}}</td>\r\n                                    <td>{{viaje.destino}}</td>\r\n                                    <td><input class=\"fourRounded\" placeholder=\"\" aria-controls=\"tableModal\" [ngModel]=\"viaje.tarifa\" (ngModelChange)=\"actualizarTarifa(proforma, viaje, $event)\"> $/Tns</td> <!--(ngModelChange)=\"viaje.tarifa = $event\"-->\r\n                                    <td>{{viaje.peajeString}}</td>\r\n                                    <td>{{viaje.playaString}}</td>\r\n                                    <td><span>AR$ </span>{{viaje.importeString}}</td>\r\n                                </tr>\r\n                            </tbody>\r\n                        </table>\r\n                        <!--guardar proforma-->\r\n                        <div class=\"row myRow\">\r\n                            <div class=\"clearfix totalTable\">\r\n                                <table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n                                    <tr>\r\n                                        <td>TOTAL</td>\r\n                                        <td>\r\n                                            <p>Kg netos</p>\r\n                                            {{proforma.totalKg}}\r\n                                        </td>\r\n                                        <td>\r\n                                            <p>Importe</p>\r\n                                            {{proforma.totalImporteString}}\r\n                                        </td>\r\n                                    </tr>\r\n                                </table>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <!--footer proforma-->\r\n                    <hr>\r\n                    <div class=\"col-xs-12 col-sm-3 col-md-3 col-sm-offset-6 fletesActions\" id=\"validarFletes\" (click)=\"validarImporte(proforma)\">\r\n                        <!--(click)=\"showModalCargaDatos(proforma.proforma)\"-->\r\n                        <a href=\"#\" style=\"text-decoration:none!important\">\r\n                            <div class=\"btnSection animate\">Validar <span class=\"fa  fa-floppy-o\"></span></div>\r\n                        </a>\r\n                    </div>\r\n                    <div id=\"closeDetalleFletes\" onClick=\"closeDetalleFletes(this)\" class=\"col-xs-12 col-sm-3\">\r\n                        <a (click)=\"false\" href=\"#\" style=\"text-decoration:none!important\">\r\n                            <div class=\"btnSection animate\">Detalles <span class=\"fa  fa-times\"></span></div>\r\n                        </a>\r\n                    </div>\r\n                    <div id=\"openDetalleFletes\" onClick=\"openDetalleFletes(this)\" class=\"col-xs-12 col-sm-3 col-sm-offset-9 \">\r\n                        <a (click)=\"false\" href=\"#\" style=\"text-decoration:none!important\">\r\n                            <div class=\"btnSection animate\">Detalles <span class=\"fa  fa-angle-double-right\"></span></div>\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </ng-container>\r\n    </section>\r\n    <!--End CONTENT-->\r\n</div>\r\n"

