module.exports = "<!-- Modal -->\r\n<div class=\"content-wraper\">\r\n    <!-- CONTENT-->\r\n    <section class=\"container-fluid clearfix\">\r\n        <!--Title-->\r\n        <div class=\"row titleSection\">\r\n            <div class=\"col-xs-12 col-sm-10 \">Liquidaci&oacute;n: <strong>Aprobadas</strong> </div>\r\n            <div class=\"col-xs-12 col-sm-2\">\r\n                <spinner-small></spinner-small>\r\n                <a (click)=\"exportExcel()\" href=\"#\" style=\"text-decoration:none!important\" *ngIf=\"!this.spinnerSmallComponent.visible\">\r\n                    <div class=\"btnSection animate\">Exportar <span class=\"fa  fa-file-excel-o\"></span></div>\r\n                </a>\r\n            </div>\r\n        </div>\r\n        <!--End Title-->\r\n        <!--Search-->\r\n        <div class=\"row  myRow firstSection mySearch\">\r\n            <div class=\"col-xs-12 col-md-12 rounded shadow animate\">\r\n                <title-caps>Refinar resultados</title-caps>\r\n                <hr />\r\n                <div id=\"searchVer\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Ver:\r\n                    <filtro-fecha (ClickEvent)=\"getData()\"></filtro-fecha>\r\n                </div>\r\n                <div id=\"searchVendedor\" class=\"col-xs-12  col-sm-6 col-md-15\">\r\n                    Por Vendedor:\r\n                    <div class=\"styled-select \">\r\n                        <dropdown [tipoDropdown]=\"'filtroVariable'\" [options]=\"filtroVendedor\" (select)=\"setFiltroVendedor($event)\"></dropdown>\r\n                    </div>\r\n                </div>\r\n                <div id=\"searchProducto\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Por Producto:\r\n                    <div class=\"styled-select \">\r\n                        <dropdown [tipoDropdown]=\"'filtroVariable'\" [options]=\"filtroObservacion\"></dropdown>\r\n                    </div>\r\n                </div>\r\n                <div id=\"searchContrato\" class=\"col-xs-12 col-sm-6 col-md-15 \">\r\n                    Por Comprobante o Contrato:\r\n                    <div class=\"styled-select \">\r\n                        <input type=\"search\" class=\"\" placeholder=\"\" [value]=\"filtroComprobanteOContrato\" (input)=\"filtroComprobanteOContrato = $event.target.value\" aria-controls=\"tableModal\">\r\n                    </div>\r\n                </div>\r\n                <div id=\"searchMostrar\" class=\"col-xs-12 col-sm-6 col-md-15\">\r\n                    Mostrar:\r\n                    <div class=\"styled-select \">\r\n                        <dropdown [tipoDropdown]=\"'numberItems'\" (select)=\"setItemsPerPage($event)\"></dropdown>\r\n                    </div>\r\n                </div>\r\n                <div id=\"showSearch\" onClick=\"openSearch()\">\r\n                    <div style=\"\">\r\n                        <div class=\"fa fa-angle-double-right\" aria-hidden=\"true\"></div>\r\n                    </div>\r\n                    <div>VER MÁS OPCIONES DE BÚSQUEDA</div>\r\n                </div>\r\n                <div id=\"hideSearch\" onClick=\"closeSearch()\">\r\n                    <div style=\"\">\r\n                        <div class=\"fa fa-times\" aria-hidden=\"true\"></div>\r\n                    </div>\r\n                    <div>OCULTAR OPCIONES DE BÚSQUEDA</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- End Search-->\r\n        <!-- Tables-->\r\n\r\n        <div class=\"row myRow\">\r\n            <div class=\"clearfix myTables\">\r\n\r\n                <mensaje></mensaje>\r\n                <spinner></spinner>\r\n\r\n                <table *ngIf=\"isVisible()\" id=\"tableModal\" class=\"display nowrap dataTable no-footer dtr-inline rounded shadow animate liquidaciones-aprobadas-table\" cellspacing=\"0\" role=\"grid\" aria-describedby=\"tableModal_info\" style=\"width: 100%; padding:10px 0;\">\r\n                    <thead>\r\n                        <tr role=\"row\">\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('emitidoDate')\">Vencimiento</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('tipo')\">Tipo</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('comprobante')\">Comprobante</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('producto')\">Producto</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('liquidado')\">Liquidacion</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('importe')\">Total</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\" (click)=\"orderColumnBy('contrato')\">Contrato</th>\r\n                            <th tabindex=\"0\" rowspan=\"1\" colspan=\"1\" style=\"\">Ver CCPPs</th>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                        <tr *ngFor=\"let liquidacion of data.liquidaciones | customFilter : 'producto' : productoSelected | customFilter : 'observaciones' : observacionSelected | customFilterOr : 'contrato' : 'comprobante' : filtroComprobanteOContrato | orderedColumn : {property: orderedByColumn, direction: orderDirection} | paginate: { itemsPerPage:itemsPerPage, currentPage: p } ; let odd = odd\" role=\"row\" [class.odd]=\"!odd\">\r\n                            <td><a (click)=\"showModalTableResponsive(liquidacion)\" class=\"btnShowModal\"><i class=\"fa fa-plus fa-lg\" aria-hidden=\"true\"></i></a> {{liquidacion.emitido}}</td>\r\n                            <td>{{liquidacion.tipo}}</td>\r\n                            <td><a (click)=\"descargaPDF(liquidacion.documento, liquidacion.ejercicio)\" href=\"#\"><span class=\"fa  fa-file-pdf-o \" *ngIf=\"liquidacion.comprobante != ''\"></span> {{liquidacion.comprobante}}</a></td>\r\n                            <td>{{liquidacion.producto}}</td>\r\n                            <td>{{liquidacion.liquidadoString}}</td>\r\n                            <td>{{liquidacion.importeString}}</td>\r\n                            <td><a class=\"animate\" (click)=\"goToSeccionParam('/contrato/detalle', liquidacion.contrato)\" href=\"#\">{{liquidacion.contrato}}</a></td>\r\n                            <td><a (click)=\"showModal(liquidacion.contrato, liquidacion.secuencia, liquidacion.comprobante)\" href=\"#\" class=\"animate\"><span class=\"fa fa-search\"></span></a></td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n\r\n                <pagination-template #pT=\"paginationApi\" (pageChange)=\"p = $event\" *ngIf=\"isVisible()\">\r\n                    <div class=\"dataTables_paginate paging_simple_numbers\">\r\n                        <a id=\"tableModal_previous\" class=\"paginate_button previous\" (click)=\"pT.previous()\" [class.disabled]=\"pT.isFirstPage()\"> Anterior </a>\r\n                        <span *ngFor=\"let page of pT.pages\" [class.current]=\"pT.getCurrent() === page.value\">\r\n                            <a class=\"paginate_button\" (click)=\"pT.setCurrent(page.value)\" *ngIf=\"pT.getCurrent() !== page.value\">{{ page.label }}</a>\r\n                            <a class=\"paginate_button current\" *ngIf=\"pT.getCurrent() === page.value\">{{ page.label }}</a>\r\n                        </span>\r\n                        <a id=\"tableModal_next\" class=\"paginate_button next\" (click)=\"pT.next()\" [class.disabled]=\"pT.isLastPage()\"> Siguiente </a>\r\n                    </div>\r\n                </pagination-template>\r\n            </div>\r\n        </div>\r\n        <!-- END tables-->\r\n    </section>\r\n    <!--End CONTENT-->\r\n</div>\r\n"

