module.exports = "<div class=\"content-wraper ccpp\">\r\n    <!-- CONTENT-->\r\n    <mensaje></mensaje>\r\n    <spinner></spinner>\r\n    <section class=\"container-fluid clearfix\" *ngIf=\"data != undefined\">\r\n        <!--Title-->\r\n        <div class=\"row titleSection titleSectionTable\">\r\n            <div class=\"col-xs-12 col-sm-10 fixtwobuttons titleSectionTablePart animate\" style=\"vertical-align:bottom;\">\r\n                <div style=\"line-height:0.8; display: inline-block; vertical-align:top;\"> Proforma de Liquidaci&oacute;n Final: <strong><span>Nº {{data.fijacion}}</span></strong> </div>\r\n            </div>\r\n            <div class=\"col-xs-12 col-sm-2 titleSectionTablePart\">\r\n                <spinner-small #smallSpinner></spinner-small>\r\n                <a (click)=\"exportExcel()\" href=\"#\" style=\"text-decoration:none!important\" *ngIf=\"!this.spinnerSmallComponent.visible\">\r\n                    <div class=\"btnSection animate\">Exportar <span class=\"fa  fa-file-excel-o\"></span></div>\r\n                </a>\r\n                <!--<a href=\"#\" style=\"text-decoration:none!important\">\r\n                    <div class=\"btnSection animate print\">Imprimir <span class=\"fa  fa-print\"></span></div>\r\n                </a>-->\r\n            </div>\r\n        </div>\r\n        <!--End Title-->\r\n        <!--Datos de Pago-->\r\n        <div id=\"Pago\" class=\" firstSection row myRow\">\r\n            <div class=\"row titleSection titleSectionNoBorder\">\r\n                <div class=\"col-xs-12 rowInfoGrey rounded shadow animate rowInfoRoundedGreen\">\r\n                    <div class=\"rowInfoRoundedGreenLine\">\r\n                        <div class=\"col-xs-12 col-sm-2\">\r\n                            <p>Precio</p>\r\n                            <p>{{data.cabecera.precioString}}</p>\r\n                        </div>\r\n                        <div class=\"col-xs-12 col-sm-2\">\r\n                            <p>Flete $/Ton</p>\r\n                            <p>{{data.cabecera.tarifaFleteString}}</p>\r\n                        </div>\r\n                        <div class=\"col-xs-12 col-sm-2\">\r\n                            <p>Precio Neto</p>\r\n                            <p>{{data.cabecera.precioNetoString}}</p>\r\n                        </div>\r\n                        <div class=\"col-xs-12 col-sm-3\">\r\n                            <p>Kilos Compra</p>\r\n                            <p>{{data.cabecera.compradosString}}</p>\r\n                        </div>\r\n                        <div class=\"col-xs-12 col-sm-3\">\r\n                            <p>Kilos Recibidos</p>\r\n                            <p>{{data.cabecera.recibidosString}}</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!--factura-->\r\n        <div id=\"Pago\" class=\"Pago\">\r\n            <div class=\"PagoColumn\">\r\n                <table class=\"CalidadCCPP\" width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n                    <tr>\r\n                        <td width=\"100%\">\r\n                            <div>\r\n                                <p>Contrato Molinos</p>\r\n                                <p> <a class=\"animate\" (click)=\"goToSeccionParam('/contrato/detalle', data.salidas[0].contrato)\" href=\"#\">{{data.salidas[0].contrato}}</a></p>\r\n                            </div>\r\n                            <div>\r\n                                <p> Tipo pago</p>\r\n                                <p>Liq.</p>\r\n                            </div>\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n            </div>\r\n            <div class=\"PagoFactura\">\r\n                <table class=\"PagoTable rounded shadow animate\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"width: 100%;\">\r\n                    <tr class=\"CalidadCCPPDataCategoria\">\r\n                        <th width=\"40%\">&nbsp;</th>\r\n                        <th width=\"20%\">Importe</th>\r\n                        <th width=\"20%\">IVA</th>\r\n                        <th width=\"20%\">Total</th>\r\n                    </tr>\r\n                    <ng-container *ngFor=\"let salida of data.salidas\">\r\n                        <tr class=\"PagoTableLine\">\r\n                            <td *ngIf=\"salida.caracteristica.toUpperCase() == 'FLETE PROCEDENCIA'\"><a class=\"PagoTablaLink\" (click)=\"showModalProcedencia(data.fijacion)\" href=\"#\">{{salida.caracteristica}}</a></td>\r\n                            <td *ngIf=\"salida.caracteristica.toUpperCase() != 'FLETE PROCEDENCIA'\">{{salida.caracteristica}}</td>\r\n                            <td><span [ngClass]=\"(isNegative(salida.importe)) ? 'PagoNegative' : 'PagoPositive'\">{{salida.importeString}}</span></td>\r\n                            <td><span [ngClass]=\"(isNegative(salida.iva)) ? 'PagoNegative' : 'PagoPositive'\"> {{salida.ivaString}}</span></td>\r\n                            <td><span [ngClass]=\"(isNegative(salida.total)) ? 'PagoNegative' : 'PagoPositive'\">{{salida.totalString}}</span></td>\r\n                        </tr>\r\n                    </ng-container>\r\n                    <tr>\r\n                        <td>{{data.subTotal.caracteristica}}</td>\r\n                        <td><span [ngClass]=\"(isNegative(data.subTotal.importe)) ? 'PagoNegative' : 'PagoPositive'\">{{data.subTotal.importeString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.subTotal.iva)) ? 'PagoNegative' : 'PagoPositive'\"> {{data.subTotal.ivaString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.subTotal.total)) ? 'PagoNegative' : 'PagoPositive'\">{{data.subTotal.totalString}}</span></td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>{{data.pagoACuenta.caracteristica}}</td>\r\n                        <td><span [ngClass]=\"(isNegative(data.pagoACuenta.importe)) ? 'PagoNegative' : 'PagoPositive'\">{{data.pagoACuenta.importeString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.pagoACuenta.iva)) ? 'PagoNegative' : 'PagoPositive'\"> {{data.pagoACuenta.ivaString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.pagoACuenta.total)) ? 'PagoNegative' : 'PagoPositive'\">{{data.pagoACuenta.totalString}}</span></td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>{{data.saldoAPagar.caracteristica}}</td>\r\n                        <td><span [ngClass]=\"(isNegative(data.saldoAPagar.importe)) ? 'PagoNegative' : 'PagoPositive'\">{{data.saldoAPagar.importeString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.saldoAPagar.iva)) ? 'PagoNegative' : 'PagoPositive'\"> {{data.saldoAPagar.ivaString}}</span></td>\r\n                        <td><span [ngClass]=\"(isNegative(data.saldoAPagar.total)) ? 'PagoNegative' : 'PagoPositive'\">{{data.saldoAPagar.totalString}}</span></td>\r\n                    </tr>\r\n                </table>\r\n            </div>\r\n        </div>\r\n        <!--Botones mobile-->\r\n        <div class=\"showBtn btnSection btnInfo animate  downloadPDF downloadPDF_PAGO\">\r\n            <a href=\"#\">\r\n                <div>\r\n                    <li class=\"fa fa-file-pdf-o\" aria-hidden=\"true\"></li>\r\n                </div>\r\n                <div>Factura</div>\r\n            </a>\r\n        </div>\r\n        <!--Fin botones mobile-->\r\n    </section>\r\n    <!--End CONTENT-->\r\n</div>\r\n"

